def get_cs2023_parallel_catalog() -> List[Cs2023ParallelRecord]:
    """Return complete cs2023_parallel registry."""
    return REGISTRY_CS2023_PARALLEL


def query_cs2023_parallel_by_difficulty(difficulty_level: str) -> List[Cs2023ParallelRecord]:
    """Filter cs2023_parallel elements matching difficulty."""
    return [item for item in REGISTRY_CS2023_PARALLEL if item.difficulty == difficulty_level]


def calculate_cs2023_parallel_total_weight() -> float:
    """Compute cumulative weighting of curriculum units."""
    return sum(item.weight for item in REGISTRY_CS2023_PARALLEL)

